/*
 * A102036  Triangle, read by rows, where the terms are generated by the rule:
 *          T(n,k) = T(n-1,k) + T(n-1,k-1) + T(n-2,k-1) + T(n-3,k-1), with
 *          T(0,0)=1.
 * https://oeis.org/A102036
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 38, u16 n <= 65, u32 n <= 65, u64 n <= 65, u128 n <= 65,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  OEIS A102036
 *
 *  Triangle read by rows.  The sequence a(n) is the nth term in the
 *  triangle when it is read row by row.  The triangle is generated by:
 *
 *      T(0,0) = 1
 *      T(n,k) = T(n-1,k) + T(n-1,k-1) + T(n-2,k-1) + T(n-3,k-1)
 *               (with T(x,y) = 0 if x < 0 or y < 0 or y > x)
 *
 *  The function builds the triangle incrementally and stores the flattened
 *  values in an array.  Only a small fixed amount of memory is used
 *  – 4 rows of width 20001 and an output buffer of length 20001.  This
 *  satisfies the limits for n ≤ 20000 (corresponding to flattened index;
 *  the corresponding triangle depth is only ≈ 141).  The computation
 *  costs O(n) where n is the requested index.
 */

#include <stdint.h>
#include <stdbool.h>

/* Adjust this limit if a larger index n is required. */
#define MAX_FLAT 20000        /* maximum flattened index that may be queried */

/* Global static storage */
static seq_t rows[4][MAX_FLAT + 1];      /* buffers for the last 4 rows of the triangle */
static seq_t flat_seq[MAX_FLAT + 1];     /* flattened sequence values a(n) */
static bool       initialized = false;   /* one‑time initialisation flag */
static idx_t      last_row    = 0;        /* last row that has been fully computed (0‑based) */
static idx_t      last_flat   = 0;        /* highest flattened index computed so far */

/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (!initialized) {
        /* initialise the very first row */
        rows[0][0] = (seq_t)1;
        flat_seq[0] = (seq_t)1;
        initialized = true;
    }

    if (n <= last_flat) {
        /* value already computed */
        return flat_seq[n];
    }

    /* compute rows until we have filled up to flattened index n */
    for (idx_t r = last_row + 1; ; ++r) {
        /* start index of row r */
        idx_t offset = (r * (r + 1)) / 2;
        if (offset > n) {
            /* no further rows needed */
            break;
        }

        idx_t cur  = r & 3;          /* current row buffer index   */
        idx_t p1   = (cur + 3) & 3;  /* (r-1) % 4                  */
        idx_t p2   = (cur + 2) & 3;  /* (r-2) % 4                  */
        idx_t p3   = (cur + 1) & 3;  /* (r-3) % 4                  */

        for (idx_t k = 0; k <= r; ++k) {
            seq_t val = 0;

            if (k <= r - 1)          val += rows[p1][k];      /* T(r-1,k)        */
            if (k >= 1)               val += rows[p1][k - 1];  /* T(r-1,k-1)      */
            if (r >= 2 && k >= 1)     val += rows[p2][k - 1];  /* T(r-2,k-1)      */
            if (r >= 3 && k >= 1)     val += rows[p3][k - 1];  /* T(r-3,k-1)      */

            rows[cur][k] = val;
            flat_seq[offset + k] = val;          /* store flattened value */
        }

        /* update bookkeeping */
        last_row = r;
        /* highest index now computed */
        last_flat = (offset + r <= n) ? offset + r : n;
    }

    return flat_seq[n];
}
